post_install:
import shutil,pathlib,os,stat,filecmp
src=pathlib.Path(r"{module_dir}"); dst=pathlib.Path(r"{data_dir}")/"grokbot"
dst.mkdir(parents=True,exist_ok=True)

# ---- 1. the shipped OpenSees/examples corpus: DATA ONLY ----------------------------------------
# Two of its folders must not land where they appear to belong:
#   indexes/  flattened into dst/indexes it shares four filenames with the PDF converter's output,
#             and the first conversion overwrote them. It gets a folder of its own.
#   scripts/  the distributable packer froze a COPY of retrieval.py, build_index.py and search.py
#             into this bundle. Copied over the workspace it silently reverted the retrieval code
#             to that snapshot -- so every query on this machine was answered by months-old code
#             while the module checkout beside it was current and `Update` reported success. The
#             bundle ships data; the code comes from the module, and only from the module.
p2=src/"engineering_rag_phase2"
if p2.is_dir():
    for c in p2.iterdir():
        if c.name == "scripts":
            continue
        if c.name == "indexes":
            shutil.copytree(c, dst/"engineering_rag_phase2"/"indexes", dirs_exist_ok=True)
            for f in ("aliases.json","master_toc.json"):
                if (c/f).is_file() and not (dst/"indexes"/f).is_file():
                    (dst/"indexes").mkdir(parents=True,exist_ok=True); shutil.copy2(c/f, dst/"indexes"/f)
            continue
        t=dst/c.name
        if c.is_dir(): shutil.copytree(c,t,dirs_exist_ok=True)
        else: shutil.copy2(c,t)

# ---- 2. the module's scripts, LAST, so code always wins over anything a data bundle carries -----
# The workspace keeps its own copy because the tabs and the grounding server run from the workspace
# and retrieval.find_root expects scripts/ beside documents/. Copied file by file with the
# read-only bit cleared, because copytree leaves a read-only destination in place without a word.
if (src/"scripts").is_dir():
    (dst/"scripts").mkdir(parents=True, exist_ok=True)
    replaced, failed = [], []
    for f in sorted((src/"scripts").rglob("*")):
        if f.is_dir() or "__pycache__" in f.parts:
            continue
        t = dst/"scripts"/f.relative_to(src/"scripts")
        t.parent.mkdir(parents=True, exist_ok=True)
        if t.is_file() and t.stat().st_size == f.stat().st_size and t.read_bytes() == f.read_bytes():
            continue
        try:
            if t.exists():
                os.chmod(t, stat.S_IWRITE | stat.S_IREAD)
            shutil.copy2(f, t)
            replaced.append(f.name)
        except OSError as e:
            failed.append(f"{f.name} ({e.__class__.__name__})")
    if replaced:
        print("[grokbot] workspace scripts refreshed:", ", ".join(replaced))
    if failed:
        print("[grokbot] COULD NOT REFRESH:", ", ".join(failed))
        raise SystemExit("[grokbot] the workspace code is older than the module -- queries would use the OLD code")

# ---- 3. prove it, rather than assume it --------------------------------------------------------
# This check is the whole reason the fault above survived four rounds of fixes: nothing ever
# compared the code the server imports with the code that was installed.
stale=[]
for n in ("retrieval.py","build_index.py","search.py"):
    a, b = src/"scripts"/n, dst/"scripts"/n
    if not a.is_file():
        continue
    if not b.is_file() or a.read_bytes() != b.read_bytes():
        stale.append(n)
if stale:
    raise SystemExit("[grokbot] workspace code does not match the module: " + ", ".join(stale))

for d in ("documents/standards","queue/in","queue/out","queue/done","markdown"):
    (dst/d).mkdir(parents=True,exist_ok=True)
print("[grokbot] workspace ready at", dst)
print("[grokbot] put your licensed spec PDFs in", dst/"documents"/"standards")
